fn r#test_build_empacota_o_backend_so_com_pyinstaller(__args: Args) -> Object {
    let mut r#source = Object::Unbound;
    r#source = object::call_method(
        &object::div(&__const__ROOT(), &object::str_("build-hybrid.py")),
        "read_text",
        Args::new(vec![], vec![("encoding", object::str_("utf-8"))]),
    );
    object::assert_(
        &object::not_in(
            &object::str_("nuitka"),
            &object::call_method(
                &object::local(&r#source, "source"),
                "lower",
                Args::new(vec![], vec![]),
            ),
        ),
        "unit/test_build_hybrid_secrets_guard.py:180",
        None,
    );
    object::assert_(
        &object::not_in(
            &object::str_("backend.pyd"),
            &object::local(&r#source, "source"),
        ),
        "unit/test_build_hybrid_secrets_guard.py:181",
        None,
    );
    object::assert_(
        &object::in_(
            &object::str_("\"--collect-submodules\", \"backend\""),
            &object::local(&r#source, "source"),
        ),
        "unit/test_build_hybrid_secrets_guard.py:182",
        None,
    );
    object::assert_(
        &object::in_(
            &object::str_("\"--collect-data\", \"backend\""),
            &object::local(&r#source, "source"),
        ),
        "unit/test_build_hybrid_secrets_guard.py:183",
        None,
    );
    object::assert_(
        &object::not_in(&object::str_("--jobs"), &object::local(&r#source, "source")),
        "unit/test_build_hybrid_secrets_guard.py:184",
        None,
    );
    Object::None
}

